$path='C:\Users\pc\Desktop\TheBlackLilyBloomsinHerEyes\chinese-patch\source\data\scenario\zh-CN\story\chapter2s2.ks'
$m=@{
'#壱十'='#壹十'; '#ひとみ'='#瞳'; '#世界'='#世界'; '#例ちゃん先輩'='#例前辈';
260='在去咖啡店的路上，世界小姐教了我一点关于魔法的事。[p]';261='她说话虽然直来直去，却会回答问题；没想到外表如此强烈，意外地还挺会照顾人。[p]';264='「喂――我来了！」[p]';267='不过，她无视着“close”的牌子打开店门，深夜里还大声宣布到访，果然还是很蛮横。[p]';268='明明这是她熟悉得不能再熟悉的打工地点，我却不由得躲到了世界小姐身后。[p]';270='「听见了。所以安静一点。」[p]';272='柜台深处传来熟悉的少女声音。[p]';275='没过多久，例前辈便现身了。[p]';278='「哟！好久不见，例前辈。」[p]';280='「好慢。从约定时间起我等了十五分钟。」[p]';282='「抱歉抱歉，路边捡到点东西。」[p]';284='「捡到东西……？」[p]';287='听到例前辈的回答，世界小姐抓住我的后颈，把我拉到她面前。[p]';289='「壹十？你怎么会在这里？」[p]';291='「呃，那个……我被卷进魔法里了。」[p]';293='「……这样啊。」[p]';296='也许从我嘴里说出的“魔法”一词就让她明白了来龙去脉，例前辈只说了这一句，便和世界小姐一起把我迎进店里。[p]';303='「……壹十、世界，咖啡请用。」[p]';305='「哦，谢谢。」[p]';307='「谢谢您，前辈。」[p]';309='我们在她带领的座位坐下，例前辈端来了平时的咖啡。[p]';310='我把桌上的一块方糖融化，慢慢从杯沿含入口中。[p]';311='浓烈苦味中的淡淡甜味调和在一起，让心情平静下来。[p]';312='我不由得呼出一口气，这才意识到自己一直在紧张。[p]';315='「呼――！果然例前辈的咖啡最棒！」[p]';317='和花时间品味的我相反，世界小姐把咖啡一饮而尽。[p]';319='哪有人像喝酒一样灌咖啡……正如第一印象，她做什么都豪放。[p]';323='「那么，进展如何？我接到仪式终于开始的报告，才被派过来的。」[p]';325='「比预想中开始得早。不过目前好像还没有大的动静。」[p]';327='终于开始了――也就是说，这个仪式或许早就能在一定程度上预测。[p]';328='至于是像天气预报一样测量自然现象，还是估算人为魔法的动向，就不得而知了。[p]';331='「除了我以外，还有人在行动吗？」[p]';333='「战华现在正在城里巡查。」[p]';335='「铃之持有者呢？」[p]';337='「世界和战华……还有壹十。然后，小清水家大概也有一只……另外三只，不明。」[p]';340='「大体上和预想一样吗。」[p]';342='战华小姐――姑且算是例前辈认识的魔术师。[p]';343='没有提到小清水家，也没有提到我打倒的男人――塔堂雷的名字。[p]';344='我有些犹豫是否应该连同自己打倒他的事一起报告，但既然她没问，似乎也没必要主动说，于是选择沉默。[p]';345='能掌握的信息当然越多越好。[p]';346='作为交换，我问了一个问题。[p]';348='「你们从什么时候开始知道这个关于仪式的预测？」[p]';350='「大约一个月前开始看到征兆的。」[p]';352='「征兆……？」[p]';354='「和空气一样，空间中也存在看不见的魔力流动。」[p]';355='「平时它像风一样漫无目的地飘荡，但那股方向被人为操控了。」[p]';357='「可以理解成有人用吸尘器之类的东西把魔力吸到一起吗？」[p]';359='「大致可以这么理解。不过，吸尘器的位置和收集魔力的方法都被巧妙隐藏了。」[p]';360='「即使说是征兆，也只是察觉到了一点违和感。直到最近几天才知道这是仪式。」[p]';362='几天前――也就是说，发现得比想象中更加千钧一发，而且已经相当晚了。[p]';364='「所以在这么紧急、又极其危险的案件曝光后，被临时派来的就是我。」[p]';366='「世界――用表社会的话说，就像自由职业者。她不属于任何组织，是自由的魔术师。」[p]';367='「虽然粗枝大叶又粗暴，但实力是一流的――而且因为是自由身，随时都能随意叫来，这点很方便。」[p]';370='「“随意”多余了，而且我一直都是温和又礼貌的[ruby text="うけおいにん"]承包人。」[p]';372='「世界也会说有趣的笑话呢。」[p]';374='面对例前辈粗略的介绍，世界小姐也用粗略的自我介绍纠正。[p]';375='虽说只是感觉，但平时寡言的例前辈能如此流畅地聊天，也能看出两人之间有着长久的信赖关系。[p]';376='神上园世界小姐。正如例前辈所评价的实力一流，她身上散发着连外行都能察觉的气场，[p]';377='她一定是个真正厉害的人。[p]';379='「也不完全是。世界确实是有实力的魔术师――也是[ruby text="うけおいにん"]承包人，但她负责的委托成功率本身并不算高。」[p]';382='「咦，是这样吗？」[p]';384='「不过，她负责的工作一定会迎来正确的结局。所以这次才叫来了世界。」[p]';388='成功率明明很低，却一定会迎来正确结局。[p]';389='我不太明白这句话的真意，但她果然是个厉害的人吧。[p]';390='例前辈经常用含蓄的说法，我没有多想。[p]';391='而且，也许是被例前辈否定了“没那么厉害”，世界小姐正用不悦的眼神瞪着我，[p]';392='我也想尽快换个话题。[p]';393='她既是厉害的人，果然也是可怕的人。[p]';395='「那么――世界小姐，现在发生的仪式具体是什么样的？」[p]';398='「具体来说嘛……你也在白色空间里被奇怪的家伙搭话了吧？它说了什么？」[p]';400='「呃……好像是“如果能实现一个愿望”之类的……」[p]';402='这里我没有撒谎。铃之持有者世界小姐应该也被问过同样的问题。[p]';403='而且要谈正题，就避不开这个前提――愿望。[p]';405='「那个，真的存在这种――能实现愿望的仪式吗？」[p]';407='是否能实现。对希望愿望成真――希望她复活的我来说，这是最重要的一点。[p]';409='「结论先说，我不知道。」[p]';411='「不知道……意思是，不知道任何愿望都能不能实现吗？」[p]';413='「在那之前，连“愿望会实现”这句话本身都很可疑。」[p]';414='「再说，能实现愿望这种方便的魔法，至少在现代已知的魔法史中并不存在。」[p]';416='「也就是说……连实现愿望的仪式也是谎言……」[p]';418='「也不能这么断定。因为这个仪式没有完全一致的先例。」[p]';420='「没有先例……这是第一次举行的仪式吗？」[p]';422='「虽然留下过类似仪式的记录。听说那场仪式最后恶魔现身，把参加者全杀了。」[p]';424='类似的仪式――也就是有七名参加者彼此争斗，最后胜者完成仪式的记录。[p]';425='那么，那场仪式的内容是谎言吗？还是仪式是真的――胜者许愿让恶魔现身，才导致了那个结果？[p]';427='「不管怎样，参加者全灭，所以详情不明。报告里只留下了讨伐恶魔时很艰苦的后续处理记录。」[p]';430='「因为留下了这种靠蛮力解决的传承，所以才叫来了我这个武斗派。」[p]';432='「……原来如此。」[p]';434='虽然只是大概，但即使对魔法理解很浅，我也感觉自己掌握了事态。[p]';435='现在的仪式详情不明。过去的类似事例，是以恶魔现身[ruby text="もっ"]为终点完成的。[p]';436='而关键的愿望能否实现――也不能断言完全不可能。[p]';438='「――那么，你想怎么办？」[p]';440='「想怎么办……您是指？」[p]';442='「就是字面意思。无论过去或传承如何，既然仪式已经在这里开始，就有某个带着目的发动它的魔术师存在――」[p]';443='「而被卷入仪式、被迫持有铃的你，无论如何都会成为那个魔术师的目标。」[p]';444='「说不定还会被杀掉夺走铃。」[p]';446='世界小姐将明确的最坏结局――死亡的警告摆在面前，向我发问。[p]';449='「你要是想放弃那东西，我就把你打趴下抢过来。」[p]';450='「这样至少能退出被魔法支配的仪式舞台。不过――」[p]';452='「――如果我还不想放弃，能请你等一等再抢吗？」[p]';454='「你可能会遇到危险哦？」[p]';456='「即使如此……我已经知道了魔法这个世界。」[p]';457='「即便最后要归还给世界小姐的铃，我也想见证到最后。」[p]';459='实现性不能断言完全没有。[p]';460='只是因为牵涉魔法这种不可思议的现象，所以既不能完全肯定，也不能完全否定。[p]';461='刚才的回答几乎等同于否定――像是在宣告我放弃那不切实际的希望。[p]';462='但是，不可能本身也不可能――可能性并非为零。[p]';463='即使从魔术师角度看仍留有万分之一，继续把性命押上去也已经足够成为理由。[p]';465='「这样啊，那就努力吧。你的铃是你的东西，负起责任照看到最后。」[p]';467='「这听起来像在养宠物……」[p]';470='「例前辈，这样可以吗？」[p]';473='「嗯，可以。壹十想怎么做，就怎么做最好。」[p]';475='「……谢谢。」[p]';477='事情比预想中更轻易地得到认可，我反而有些失落。[p]';478='我想，如果刚才点头，世界小姐大概会把我狠狠揍一顿，再夺走铃的魔力。[p]';479='即使不交手，也能明白我们之间有那样的实力差距。[p]';480='所以我本以为她会不由分说地抢走铃，没想到竟允许我继续持有，多少有些惊讶。[p]';481='也许是一种余裕――她判断外行人的行动不会影响大局。[p]';482='无论如何，能继续保有参加仪式的资格就好。[p]';483='如果最终要实现愿望，我迟早也必须和世界小姐交手。[p]';484='但能多得到一点思考时间，实在值得庆幸。[p]';498='之后，例前辈和世界小姐开始商量今后的方针――[p]';499='而我因为时间已晚、明天还要上学，被要求先回家。[p]';500='回去时是老板开车送我的。一路上以及回到家后，铃都没有发出声音。[p]';502='回家后洗澡、准备睡觉的期间，我一直在思考魔法。[p]';503='直到昨天都不知道的里世界――魔法，以及实现愿望的仪式。[p]';504='当然，我也思考了明天之后该如何行动。[p]';505='比如，收集铃之魔力的方法。[p]';506='听例前辈说，铃的力量似乎只有夜晚才会起作用，[p]';507='所以如果要收集，就得像今天原本打算的那样，依靠瞳的直觉在夜晚的街道上徘徊。[p]';508='不过，比起这些，我想得更多的是魔法――这种未知力量的存在。[p]';510='世界小姐说过，不存在能实现愿望的魔法。[p]';511='但她也暗示过，像没有先例的仪式一样――世上仍可能存在身份不明的力量。[p]';512='说不定世界某处真的存在能让死者复活的魔法。[p]';513='即便不是――也许存在能治好瞳疾病的魔法。[p]';514='如果我当时知道魔法――也许就能避免失去她。这个不可能的假设在脑中盘旋。[p]';518='「……壹十。抱歉在你期待时泼冷水……」[p]';519='「我觉得魔法肯定没那么万能。」[p]';521='瞳――从我的俯瞰视角所见的幻想，对自己泼了冷水。[p]';523='「对我们来说，魔法是未知，是幻想的具现，也像装满梦想的魔法灯，但即便如此――」[p]';524='「如果魔法真是那样万能的力量，早就该为世人所知――」[p]';526='「――世界本应变得更美好，不是吗？」[p]';528='我明白。其实在内心某处，我早就察觉到了。[p]';529='这个世界不存在奇迹。人不可能靠魔法复活。[p]';530='但――如果“万一”、如果希望、如果可能性仍然存在。[p]';531='哪怕要依靠魔法的力量――依靠[ruby text="うたかた"]泡沫般的奇迹，[p]';532='#壹十';533='「……对不起，瞳。一直让你陪着我任性。」[p]';536='「没关系。直到壹十满意为止，我会一直陪着你。」[p]';538='我伸手向幻影的肩膀，弯曲的指尖划过空气。[p]';539='我想把因破灭的希望泡沫而落泪的时刻，再稍微推迟一些。[p]'
}
$lines=[System.Collections.Generic.List[string]](Get-Content $path -Encoding UTF8)
foreach($n in $m.Keys){ if($n -is [int]){$lines[$n-1]=$m[$n]} else {for($i=0;$i -lt $lines.Count;$i++){if($lines[$i] -eq $n){$lines[$i]=$m[$n]}}}}
[IO.File]::WriteAllLines($path,$lines,[Text.UTF8Encoding]::new($false))
